/** Functions for the parsing and (inter-)conversion of {@link ItemBundle} lists. */

import { cloneDeep, clone } from "lodash-es";

import { isArray, entries, isInteger, logger, keys } from "../common";

type PropValidator<T extends keyof ItemProperties> = (property: unknown, asset: Asset) => property is NonNullable<ItemProperties[T]>;
type PropMappingType = {[T in keyof ItemProperties]?: PropValidator<T>};

/** Validation function for the {@link ItemProperties.OverrideHeight} property. */
function validateOverrideHeight(property: unknown, asset: Asset): property is AssetOverrideHeight {
    const data = VariableHeightDataLookup[`${asset.Group.Name}${asset.Name}`];
    if (data === undefined) {
        return false;
    }

    const p = <AssetOverrideHeight | null>property;
    return (
        p !== null
        && typeof p === "object"
        && Number.isInteger(p.Priority)
        && (
            typeof p.Height === "number"
            && p.Height <= data.maxHeight
            && p.Height >= data.minHeight
        )
        && (
            p.HeightRatioProportion == null
            || (
                typeof p.HeightRatioProportion === "number"
                && p.HeightRatioProportion >= 0
                && p.HeightRatioProportion <= 1
            )
        )
    );
}

/** Validation function for the {@link TextItemNames} properties. */
function validateText(field: TextItemNames, property: unknown, asset: Asset): property is string {
    if (typeof property !== "string" || !DynamicDrawTextRegex.test(property)) {
        return false;
    }

    const key = `${asset.Group.Name}${asset.Name}`;
    const [_, data] = entries(TextItemDataLookup).find(([k]) => k.includes(key)) ?? ["", null];
    return (
        data !== null
        && property.length <= (data.maxLength[field] ?? -1)
    );
}

type Prop = Required<ItemProperties>;

/**
 * A record {@link ItemProperties} with validation functions.
 * Properties are limited to a subset that are not managed by the extended item type-setting machinery.
 */
const PROP_MAPPING: Readonly<PropMappingType> = Object.freeze({
    OverridePriority: (p, a): p is Prop["OverridePriority"] => {
        if (isInteger(p)) {
            return true;
        } else if (CommonIsObject(p)) {
            const layers = a.Layer.map(l => l.Name ?? a.Name);
            return entries(p).every(([k, v]) => layers.includes(k) && isInteger(v));
        } else {
            return false;
        }
    },
    Opacity: (p, a): p is Prop["Opacity"] => {
        if (typeof p === "number") {
            return p <= 1 && p >= 0;
        } else if (isArray(p)) {
            return p.every((opacity, i) => {
                const layer = a.Layer[i];
                return (
                    layer != null
                    && typeof opacity === "number"
                    && opacity <= 1
                    && opacity >= 0
                );
            });
        } else {
            return false;
        }
    },
    Text: (p, a): p is Prop["Text"] => validateText("Text", p, a),
    Text2: (p, a): p is Prop["Text2"] => validateText("Text2", p, a),
    Text3: (p, a): p is Prop["Text3"] => validateText("Text3", p, a),
    ShowText: (p, _): p is Prop["ShowText"] => typeof p === "boolean",
    TriggerValues: (p, _): p is Prop["TriggerValues"] => typeof p === "string" && p.split(",").length === ItemVulvaFuturisticVibratorTriggers.length,
    AccessMode: (p, _): p is Prop["AccessMode"] => typeof p === "string" && ItemVulvaFuturisticVibratorAccessModes.includes(<"" | "ProhibitSelf" | "LockMember">p),
    PunishOrgasm: (p, _): p is Prop["PunishOrgasm"] => typeof p === "boolean",
    PunishStandup: (p, _): p is Prop["PunishStandup"] => typeof p === "boolean",
    Texts: (p, _): p is Prop["Texts"] => {
        if (!Array.isArray(p)) {
            return false;
        }
        if (p.length < ItemDevicesLuckyWheelMinTexts || p.length > ItemDevicesLuckyWheelMaxTexts) {
            return false;
        }
        return p.every(i => typeof i === "string" && i.length <= ItemDevicesLuckyWheelMaxTextLength);
    },
    TargetAngle: (p, _): p is Prop["TargetAngle"] => typeof p === "number" && p >= 0 && p <= 360,
    OverrideHeight: validateOverrideHeight,
    PunishActivity: (p, _): p is Prop["PunishActivity"] => typeof p === "boolean",
    PunishStruggle: (p, _): p is Prop["PunishStruggle"] => typeof p === "boolean",
    PunishStruggleOther: (p, _): p is Prop["PunishStruggleOther"] => typeof p === "boolean",
    PunishRequiredSpeechWord: (p, _): p is Prop["PunishRequiredSpeechWord"] => typeof p === "string" && p.length <= 70,
    PunishProhibitedSpeechWords: (p, _): p is Prop["PunishProhibitedSpeechWords"] => typeof p === "string" && p.length <= 70,
    PunishSpeech: (p, _): p is Prop["PunishSpeech"] => isInteger(p) && p >= 0 && p < FuturisticTrainingBeltSpeechPunishments.length,
    PunishRequiredSpeech: (p, _): p is Prop["PunishRequiredSpeech"] => isInteger(p) && p >= 0 && p < FuturisticTrainingBeltSpeechPunishments.length,
    PunishProhibitedSpeech: (p, _): p is Prop["PunishProhibitedSpeech"] => isInteger(p) && p >= 0 && p < FuturisticTrainingBeltSpeechPunishments.length,
    PublicModeCurrent: (p, _): p is Prop["PublicModeCurrent"] => isInteger(p) && p >= 0 && p < FuturisticTrainingBeltModes.length,
    PublicModePermission: (p, _): p is Prop["PublicModePermission"] => isInteger(p) && p >= 0 && p < FuturisticTrainingBeltPermissions.length,
    ShockLevel: (p, _): p is Prop["ShockLevel"] => isInteger(p) && p >= 0 && p <= 2,
    PortalLinkCode: (p, _): p is Prop["PortalLinkCode"] => typeof p === "string" && PortalLinkCodeRegex.test(p),
    OpenPermission: (p, _): p is Prop["OpenPermission"] => typeof p === "boolean",
    OpenPermissionChastity: (p, _): p is Prop["OpenPermissionChastity"] => typeof p === "boolean",
    OpenPermissionArm: (p, _): p is Prop["OpenPermissionArm"] => typeof p === "boolean",
    OpenPermissionLeg: (p, _): p is Prop["OpenPermissionLeg"] => typeof p === "boolean",
    BlockRemotes: (p, _): p is Prop["BlockRemotes"] => typeof p === "boolean",
    LayerTranslationX: (p, a): p is Prop["LayerTranslationX"] => {
        const layers = new Set(a.Layer.map(l => l.Name ?? a.Name));
        const [min, max] = a.Group.Name === "Pussy" ? [-180, 180] : [-500, 500];
        return CommonIsObject(p) && layers.isSupersetOf(new Set(keys(p))) && Object.values(p).every(i => CommonIsInteger(i, min, max) || i === undefined);
    },
    LayerTranslationY: (p, a): p is Prop["LayerTranslationY"] => {
        const layers = new Set(a.Layer.map(l => l.Name ?? a.Name));
        const [min, max] = a.Group.Name === "Pussy" ? [-180, 180] : [-500, 500];
        return CommonIsObject(p) && layers.isSupersetOf(new Set(keys(p))) && Object.values(p).every(i => CommonIsInteger(i, min, max) || i === undefined);
    },
    LayerScaleX: (p, a): p is Prop["LayerScaleX"] => {
        const layers = new Set(a.Layer.map(l => l.Name ?? a.Name));
        const [min, max] = a.Group.Name === "Pussy" ? [0.5, 1.5] : [0.01, 3.0];
        return CommonIsObject(p) && layers.isSupersetOf(new Set(keys(p))) && Object.values(p).every(i => CommonIsFinite(i, min, max) || i === undefined);
    },
    LayerScaleY: (p, a): p is Prop["LayerScaleY"] => {
        const layers = new Set(a.Layer.map(l => l.Name ?? a.Name));
        const [min, max] = a.Group.Name === "Pussy" ? [0.5, 1.5] : [0.01, 3.0];
        return CommonIsObject(p) && layers.isSupersetOf(new Set(keys(p))) && Object.values(p).every(i => CommonIsFinite(i, min, max) || i === undefined);
    },
    LayerRotation: (p, a): p is Prop["LayerRotation"] => {
        const layers = new Set(a.Layer.map(l => l.Name ?? a.Name));
        const [min, max] = [-180, 180];
        return CommonIsObject(p) && layers.isSupersetOf(new Set(keys(p))) && Object.values(p).every(i => CommonIsInteger(i, min, max) || i === undefined);
    },
    TranslationX: (p, _): p is Prop["TranslationX"] => CommonIsInteger(p, -500, 500),
    TranslationY: (p, _): p is Prop["TranslationY"] => CommonIsInteger(p, -500, 500),
    ScaleX: (p, _): p is Prop["ScaleX"] => CommonIsFinite(p, 0.01, 3.0),
    ScaleY: (p, _): p is Prop["ScaleY"] => CommonIsFinite(p, 0.01, 3.0),
    Rotation: (p, _): p is Prop["Rotation"] => CommonIsInteger(p, -180, 180),
});

/**
 * Extract, validate and return all properties that intersect with {@link PROP_MAPPING}.
 * @param asset The relevant asset
 * @param properties The properties in question
 */
function sanitizeProperties(asset: Asset, properties?: ItemProperties): ItemProperties {
    if (properties === null || typeof properties !== "object") {
        return {};
    }

    const validPropKeys: Set<keyof ItemProperties> = new Set([
        "OverridePriority",
        asset.EditOpacity ? "Opacity" : null,
        "DrawingTop",
        "DrawingLeft",
    ].filter((i): i is keyof ItemProperties => i != null));
    if (asset.Archetype) {
        const item = AppearanceItem.fromAsset(asset, { property: properties });
        const options = ExtendedItemGatherOptions(item);
        for (const option of options) {
            if (option.OptionType === "VariableHeightOption") {
                validPropKeys.add("OverrideHeight");
            }
            for (const key of keys(option.ParentData.baselineProperty ?? {})) {
                if (!CraftingPropertyExclude.has(key)) {
                    validPropKeys.add(key);
                }
            }
        }
    }

    const ret: ItemProperties = {};
    for (const [key, value] of entries(properties)) {
        const validate = PROP_MAPPING[key];
        if (value == null || !validPropKeys.has(key) || validate === undefined) {
            continue;
        }
        if (validate(value, asset)) {
            ret[key] = value as any;
        }
    }
    return ret;
}

/** A map with various {@link Asset} validation checks for {@link fromItemBundles}. */
const UNSUPPORTED_ASSET_CHECKS = Object.freeze(new Map([
    ["Unknown asset", (asset: null | Asset) => asset == null],
    ["Unsupported owner-only asset", (asset: null | Asset) => asset?.OwnerOnly],
    ["Unsupported lovers-only asset", (asset: null | Asset) => asset?.LoverOnly],
    ["Unsupported D/S family-only asset", (asset: null | Asset) => asset?.FamilyOnly],
    ["Unsupported disabled asset", (asset: null | Asset) => !asset?.Enable],
    ["Unsupported script-asset", (asset: null | Asset) => asset?.Group?.Category === "Script"],
]));

/**
 * Convert an item bundle into a wheel of fortune item.
 * @param asset
 * @param item The original bundled item
 * @param custom
 * @returns The new wheel of fortune item
 */
export function fromItemBundle(
    asset: null | Asset,
    itemBundle: ItemBundle,
    custom: boolean = true,
): FWItem {
    for (const [msgPrefix, validationCheck] of UNSUPPORTED_ASSET_CHECKS) {
        if (validationCheck(asset)) {
            throw new Error(`${msgPrefix}: ${itemBundle.Group}${itemBundle}`);
        }
    }
    const item = ServerBundledItemToAppearanceItem("Female3DCG", itemBundle)!;
    return Object.freeze({
        Name: item.Asset.Name,
        Group: item.Asset.Group.Name,
        Custom: custom,
        Property: Object.freeze(sanitizeProperties(asset!, item.Property)),
        TypeRecord: Object.freeze(item.Property.TypeRecord),
        Color: Object.freeze(item.Color),
        Craft: Object.freeze(item.Craft),
        Equip: undefined,
    });
}

/**
 * Validate and convert a base64-deserialized {@link ItemBundle} or array thereof into a wheel of fortune item list.
 * @param items The original bundled item(s)
 * @returns The new list of wheel of fortune items
 */
export function fromItemBundles(items: ItemBundle | readonly ItemBundle[]): FWItem[] {
    if (!isArray(items)) {
        if (items !== null && typeof items === "object") {
            items = [items];
        } else {
            throw new TypeError(`Invalid "items" type: ${typeof items}`);
        }
    }

    // NOTE: Take extra care here as users can pass arbitrary arrays due to the handling of base64-decompressed data
    const ret: FWItem[] = [];
    const caughtErrors: Map<string, Error> = new Map();
    const groupsVisited: Set<AssetGroupName> = new Set();
    items.forEach((item, i)  => {
        let asset: null | Asset = null;
        try {
            asset = AssetGet("Female3DCG", item.Group, item.Name);
            const fwItem = fromItemBundle(asset, item);
            if (
                !groupsVisited.has(item.Group)
                && asset != null
                && (asset.Group.IsItem() || (asset.Group.IsAppearance() && asset.Group.AllowNone))
            ) {
                groupsVisited.add(item.Group);
                ret.push(fwItem);
            }
        } catch (ex) {
            let key = `${asset?.Group?.Name}${asset?.Name}`;
            if (key.includes("undefined")) {
                key = `Item ${i}`;
            }
            caughtErrors.set(key, <Error>ex);
        }
    });
    if (caughtErrors.size !== 0) {
        logger.log(`Failed to parse ${caughtErrors.size} of the provided items`, caughtErrors);
    }
    return ret;
}

/**
 * Convert a single wheel of fortune item into an item bundle
 * @param item The original wheel of fortune item
 * @param character
 */
export function toItemBundle(item: FWItem, character: Character): ItemBundle {
    const { Group, Name, Color, Craft, TypeRecord, Property } = item;
    const asset = AssetGet(character.AssetFamily, Group, Name);
    if (asset == null) {
        throw new Error(`Unknown asset: ${Group}${Name}`);
    }
    return ServerBundledItemFromAppearanceItem({
        ...item,
        Asset: asset,
        Difficulty: 0,
        Color: clone(Color ?? asset.DefaultColor) as BCColor[],
        Property: {
            ...cloneDeep(Property),
            TypeRecord: clone(TypeRecord),
        },
        Craft: cloneDeep(Craft),
    });
}

/**
 * Convert wheel of fortune items into an item bundle
 * @param items The original wheel of fortune items
 * @param character
 */
export function toItemBundles(items: readonly FWItem[], character: Character): ItemBundle[] {
    if (!isArray(items)) {
        throw new TypeError(`Invalid "items" type: ${typeof items}`);
    }
    return items.map(item => toItemBundle(item, character));
}
